.no-sub-news {
  padding-bottom: fluid(64, 128);
  &-list {
    display: flex;
    flex-direction: column;
    border-top: 2px solid var(--clr-border-strong);
    &-item {
      &__link {
        display: flex;
        border-bottom: 1px solid var(--clr-border-default);
        align-items: center;
        padding: var(--gutter-lg);
        transition: var(--transition-default);
        @include mq(md) {
          padding: var(--gutter-md) 0;
        }
        @include mq(sm) {
          padding: var(--gutter-sm) 0;
        }
        &:hover {
          background: var(--clr-background-default);
          .no-btn-bracket {
            color: var(--clr-text-title);
            &__text {
              margin: 0 fluid(4, 8);
            }
          }
        }
      }
      &__body {
        display: grid;
        grid-template-columns: 2fr 6fr 2fr 2fr;
        gap: var(--gutter-md);
        align-items: center;
        width: 100%;
        h3 {
          @include line-clamp(1);
        }
        .no-btn-bracket {
          justify-content: flex-end;
        }
        @include mq(md) {
          grid-template-columns: auto 1fr auto;
          gap: var(--gutter-sm);
          .no-btn-bracket {
            display: none;
          }
        }
        @include mq(sm) {
          grid-template-columns: 1fr;
          gap: var(--gutter-xs);
          .--time {
            @include font("f-body-4");
          }
        }
      }
    }
  }
  .no-view-more {
    text-align: center;
    margin-top: var(--gutter-2xl);
  }
  &-view {
    margin-top: var(--header-height);
    padding-top: fluid(64, 128);
    &__inner {
      display: flex;
      flex-direction: column;
      gap: var(--gutter-md);
    }
    &__article {
      display: flex;
      flex-direction: column;
    }
    &__head {
      display: flex;
      flex-direction: column;
      gap: var(--gutter-sm);
      padding: var(--gutter-md) 0;
      border-bottom: 1px solid var(--clr-border-default);
      border-top: 1px solid var(--clr-border-default);
    }
    &__title {
      @include font("f-heading-1");
      font-weight: 600;
      color: var(--clr-text-title);
    }
    &__info {
      @include font("f-body-3");
      color: var(--clr-text-body);
      font-family: var(--family-ui);
      display: flex;
      align-items: center;
      justify-content: space-between;
      @include mq(sm) {
        flex-direction: column;
        align-items: flex-start;
        gap: var(--gutter-xs);
      }
      &__date {
      }
    }
    &__body {
      margin-top: var(--gutter-2xl);
      padding-bottom: var(--gutter-2xl);
      border-bottom: 1px solid var(--clr-border-default);
    }
    .no-view-more {
      margin-top: var(--gutter-2xl);
      text-align: center;
    }
  }
}

