private _attachVideoHover(
  li: HTMLLIElement,
  videoUrl: string,
  figure: HTMLElement,
): void {
  const video = document.createElement("video");
  video.muted = true;
  video.loop = true;
  video.playsInline = true;
  video.preload = "none";
  figure.append(video);

  const show = (): void => figure.classList.add("is-video-active");

  const onEnter = (): void => {
    if (!video.src) {
      video.src = videoUrl;
      video.load();
    }
    void video.play().catch(() => undefined);
    if (video.readyState >= 3) {
      show();
    } else {
      video.addEventListener("canplay", show, { once: true });
    }
  };
  const onLeave = (): void => {
    video.removeEventListener("canplay", show);
    figure.classList.remove("is-video-active");
    video.pause();
  };

  li.addEventListener("pointerenter", onEnter);
  li.addEventListener("pointerleave", onLeave);

  this._videoHoverCleanups.push(() => {
    video.removeEventListener("canplay", show);
    video.pause();
    li.removeEventListener("pointerenter", onEnter);
    li.removeEventListener("pointerleave", onLeave);
  });
}

private _createModalButton(item: WorkApiItem): HTMLButtonElement {
  const button = document.createElement("button");
  button.type = "button";
  button.className =
    "no-corner-btn no-works-canvas__grid-link js-work-modal-trigger";
  button.setAttribute("aria-label", `${item.title || "Work"} modal view`);
  button.append(this._createModalButtonCorner());

