syncAfterContainerChange(): void {
  Drawer.syncNavActiveState();
  updateStaticCornerSizes();
}

dispose(): void {
  this._disposeUiToggles();
  MagneticCornerTracker.destroyAll();
  CustomCursor.dispose();
  TextReveal.dispose();
  BlockReveal.dispose();
  Marquee.dispose();
  CharBtn.dispose();
  ContactWizard.dispose();
  this._pinnedRevealRuntime.dispose();
  this._qaManager.dispose();
}

private _initUiToggles(root?: ParentNode | null): void {
  this._headerUi?.dispose();
  this._headerUi = new Header();
  this._headerUi.init();

  this._workModalUi?.dispose();
  this._workModalUi = new WorkModal({ root });
